    };
  } catch (error) {
    return {
      notFound: true
    };
  }
}

export default function BlogPost({ post, comments }) {
  const router = useRouter();

  if (router.isFallback) {
    return <div>Loading...</div>;
  }

  return (
    <>
      <Head>
        <title>{post.title} - My Blog</title>
        <meta name="description" content={post.body.substring(0, 160)} />
        <meta property="og:title" content={post.title} />
        <meta property="og:description" content={post.body.substring(0, 160)} />
      </Head>

      <article>
        <button onClick={() => router.back()}>← Back</button>

        <h1>{post.title}</h1>
        <p>{post.body}</p>

        <h2>Comments ({comments.length})</h2>
        <div className="comments">
          {comments.map(comment => (
            <div key={comment.id} className="comment">
              <h3>{comment.name}</h3>
              <p>{comment.body}</p>
              <small>By: {comment.email}</small>
            </div>
          ))}
        </div>
      </article>
    </>
  );
}
```

Uses `getStaticPaths` and `getStaticProps`. Pre-generates first 10 post pages, falls back to blocking for others. Includes ISR (revalidate: 300 seconds).

### 6. API Routes

#### /pages/api/posts/index.js
```javascript
export default function handler(req, res) {
  if (req.method === 'GET') {
    // Simulate fetching posts
    const posts = [
      { id: 1, title: 'First Post', content: 'This is the first post' },
      { id: 2, title: 'Second Post', content: 'This is the second post' }
    ];

    res.status(200).json(posts);
  } else if (req.method === 'POST') {
    const { title, content } = req.body;

    if (!title || !content) {
      return res.status(400).json({ error: 'Title and content are required' });
    }

    // Simulate creating a post
    const newPost = {
      id: Date.now(),
      title,
      content,
      createdAt: new Date().toISOString()
    };

    res.status(201).json(newPost);
  } else {
    res.setHeader('Allow', ['GET', 'POST']);
    res.status(405).end(`Method ${req.method} Not Allowed`);
  }
}
```

Handles GET (fetch posts) and POST (create post) requests.

#### /pages/api/posts/[id].js
```javascript
export default function handler(req, res) {
  const { id } = req.query;

  if (req.method === 'GET') {
    // Simulate fetching a single post
    const post = {
      id: parseInt(id),
      title: `Post ${id}`,
      content: `This is the content for post ${id}`,
      createdAt: new Date().toISOString()
    };

    res.status(200).json(post);
  } else if (req.method === 'PUT') {
    const { title, content } = req.body;

    // Simulate updating a post
    const updatedPost = {
      id: parseInt(id),
      title: title || `Post ${id}`,
      content: content || `Updated content for post ${id}`,
      updatedAt: new Date().toISOString()
    };

    res.status(200).json(updatedPost);
  } else if (req.method === 'DELETE') {
    // Simulate deleting a post
    res.status(200).json({ message: `Post ${id} deleted successfully` });
  } else {
    res.setHeader('Allow', ['GET', 'PUT', 'DELETE']);
    res.status(405).end(`Method ${req.method} Not Allowed`);
  }
}
```

Handles GET (fetch one post), PUT (update), and DELETE operations on individual posts.

### 7. Components

#### /components/AppProvider.js
```javascript
import { createContext, useContext, useState } from 'react';

const AppContext = createContext();

export function AppProvider({ children }) {
  const [theme, setTheme] = useState('light');

  return (
    <AppContext.Provider value={{ theme, setTheme }}>
      {children}
    </AppContext.Provider>
  );
}

export function useAppContext() {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useAppContext must be used within AppProvider');
  }
  return context;
}
```

Custom context provider managing theme state (light/dark). Provides `useAppContext` hook.

### 8. Styles (/styles/globals.css)

Global stylesheet with:
- Reset styles (box-sizing, margin, padding)
- Body styling (Inter font, line-height: 1.6)
- App container layout (max-width: 1200px)
- Header/nav styling
- Posts grid (responsive CSS Grid: `grid-template-columns: repeat(auto-fit, minmax(300px, 1fr))`)
- Post card styling
- Comments section styling
- Error page styling
- Button styling with hover effects

Colors: Primary blue (#0070f3), text grey (#333), border grey (#eee)

### 9. Key Observations

**Architecture:**
- Pages Router (not App Router)
- Mix of SSR (`getServerSideProps`), SSG (`getStaticProps`), and ISR (Incremental Static Regeneration)
- Client-side routing with Next.js Link and useRouter

**Data Flow:**
- Homepage: SSR, fetches latest 5 posts on each request
- Blog list: SSG with ISR (60s revalidation)
- Blog detail: SSG with pre-generated paths for first 10 posts, blocking fallback for others (300s revalidation)
- API: Mock endpoints for CRUD operations on posts

**Styling:**
- CSS-in-file (globals.css)
- No CSS-in-JS or Tailwind
- Responsive grid layout

**Context:**
- AppProvider for theme state (not currently used in UI)
- Ready for expansion

**Missing Elements:**
- No middleware.ts
- No app directory
- AI SDK dependencies present but not used in current codebase
- No database connection
- Mock API responses only

